// Fuzz the imported Overworld population (src/imported-population.js) for populate steps that need a block with no exact cell.
// Each seed stores an n x n chunk rectangle generated by the ported generator (original ids), flags every chunk unpopulated except the +x/+z
// border, and runs populateImportedColumns with a mapBlock wrapper that records every original (id:meta) whose fromOriginal is missing or
// not exact. A populate that needs one is skipped whole (skipped.unmapped); the wrapper names the culprits.
//   node tools/fuzz-imported-population.mjs [--seeds 24] [--n 8] [--first 1] [--origin-step 37] [--json out.json]
import { writeFile } from 'node:fs/promises';
import { fakeIndexedDB } from '../src/fake-indexeddb.js';
globalThis.indexedDB = fakeIndexedDB();
const { populationBlockMapperReady } = await import('../src/population-world.js');
await populationBlockMapperReady;
const { streamedSource } = await import('../src/java-world.js');
const { fromOriginal } = await import('../src/block-registry.js');
const { encodeBaseColumn } = await import('../src/whole-save-columns.js');
const { populateImportedColumns } = await import('../src/imported-population.js');
const args = process.argv.slice(2), opt = { seeds: 24, n: 8, first: 1, 'origin-step': 37 };
while (args.length) { const k = args.shift().replace(/^--/, ''); opt[k] = args.shift(); }
const out = { seeds: 0, populateCalls: 0, populated: 0, skippedUnmapped: 0, skippedFailed: 0, unmappedCells: 0, culprits: {}, perSeed: [] };
for (let s = 0; s < Number(opt.seeds); s++) {
  const seed = Number(opt.first) + s * 7919, n = Number(opt.n), origin = [(s % 5) * Number(opt['origin-step']) - 60, ((s * 3) % 7) * Number(opt['origin-step']) - 90];
  const pop = streamedSource({ seed: BigInt(seed), generationVersion: 16, originX: origin[0] * 16, originZ: origin[1] * 16, worldType: 'default', generatorOptions: '' }).population;
  const store = new Map(), coords = [], unpopulated = [];
  for (let a = 0; a < n; a++) for (let b = 0; b < n; b++) {
    const o = pop.original(a + origin[0], b + origin[1]), cells = new Uint16Array(65536);
    for (let i = 0; i < 65536; i++) { if (!o.blocks[i] && !o.metadata[i]) continue; const m = fromOriginal(o.blocks[i], o.metadata[i]); if (m) cells[i] = m.id | m.meta << 8; }
    const populated = a === n - 1 || b === n - 1;
    store.set(`${a},${b}`, encodeBaseColumn('w', a, b, cells, { terrainPopulated: populated, lightPopulated: true, biomes: new Uint8Array(256).fill(1) }));
    coords.push([a, b]); if (!populated) unpopulated.push([a, b]);
  }
  const bad = new Map();
  const mapBlock = (id, meta) => { const m = fromOriginal(id, meta); if (!m?.exact || m.id > 255) bad.set(`${id}:${meta}`, (bad.get(`${id}:${meta}`) ?? 0) + 1); return m; };
  const r = await populateImportedColumns({ population: pop, origin: { chunkX: 0, chunkZ: 0 }, worldKey: 'w', coords, unpopulated, mapBlock,
    read: async (w, cs) => cs.map(([x, z]) => store.get(`${x},${z}`)), write: async (rs) => { for (const x of rs) store.set(`${x.x},${x.z}`, x); } });
  out.seeds++; out.populateCalls += r.calls; out.populated += r.populated; out.skippedUnmapped += r.skipped.unmapped; out.skippedFailed += r.skipped.failed; out.unmappedCells += r.unmappedCells ?? 0;
  for (const [k, c] of bad) out.culprits[k] = (out.culprits[k] ?? 0) + c;
  out.perSeed.push({ seed, origin, populated: r.populated, skipped: r.skipped, unmappedCells: r.unmappedCells ?? 0, culprits: Object.fromEntries(bad), errors: r.errors });
}
console.log(JSON.stringify({ ...out, perSeed: out.perSeed.filter((p) => p.skipped.unmapped || p.skipped.failed || p.errors) }, null, 1));
if (opt.json) await writeFile(opt.json, JSON.stringify(out, null, 1));
